// Package p2p issues short-lived session tickets for direct device-to-device
// transfers and pairs the two sides of a relayed byte stream.
//
// A ticket is 32 random bytes generated by crypto/rand. It is delivered to both
// devices over the already authenticated control plane and is only useful for
// the exact (from, to) pair it was created for. Tickets expire quickly and are
// bound to a single session identifier.
package p2p

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/base64"
	"errors"
	"fmt"
	"sync"
	"time"
)

// TicketSize is the byte length of a session ticket.
const TicketSize = 32

// Errors returned by the session store.
var (
	ErrUnknownSession = errors.New("p2p: unknown session")
	ErrExpired        = errors.New("p2p: session has expired")
	ErrForbidden      = errors.New("p2p: device is not part of this session")
	ErrBadTicket      = errors.New("p2p: session ticket does not match")
)

// Session is one negotiated transfer grant between two devices.
type Session struct {
	ID        string
	Ticket    []byte
	From      string
	To        string
	CreatedAt time.Time
	ExpiresAt time.Time
}

// EncodeTicket renders a ticket for JSON transport.
func EncodeTicket(ticket []byte) string { return base64.RawURLEncoding.EncodeToString(ticket) }

// DecodeTicket parses a base64url ticket.
func DecodeTicket(value string) ([]byte, error) {
	decoded, err := base64.RawURLEncoding.DecodeString(value)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrBadTicket, err)
	}
	if len(decoded) != TicketSize {
		return nil, fmt.Errorf("%w: expected %d bytes", ErrBadTicket, TicketSize)
	}
	return decoded, nil
}

// Store keeps pending sessions in memory. Sessions are intentionally ephemeral:
// a restart invalidates every outstanding ticket, which is the safe default.
type Store struct {
	mu       sync.Mutex
	sessions map[string]*Session
	ttl      time.Duration
	now      func() time.Time
}

// NewStore creates a session store with the given ticket lifetime.
func NewStore(ttl time.Duration) (*Store, error) {
	if ttl <= 0 || ttl > 10*time.Minute {
		return nil, errors.New("p2p: session ttl must be between 1s and 10m")
	}
	return &Store{
		sessions: make(map[string]*Session),
		ttl:      ttl,
		now:      time.Now,
	}, nil
}

// SetClock overrides the clock; it exists for deterministic tests.
func (s *Store) SetClock(now func() time.Time) {
	if now != nil {
		s.now = now
	}
}

// Open creates a session between two devices.
func (s *Store) Open(from, to string) (Session, error) {
	if from == "" || to == "" || from == to {
		return Session{}, errors.New("p2p: a session needs two distinct devices")
	}

	ticket := make([]byte, TicketSize)
	if _, err := rand.Read(ticket); err != nil {
		return Session{}, fmt.Errorf("p2p: cannot generate a ticket: %w", err)
	}
	idBytes := make([]byte, 16)
	if _, err := rand.Read(idBytes); err != nil {
		return Session{}, fmt.Errorf("p2p: cannot generate a session id: %w", err)
	}

	now := s.now().UTC()
	session := &Session{
		ID:        base64.RawURLEncoding.EncodeToString(idBytes),
		Ticket:    ticket,
		From:      from,
		To:        to,
		CreatedAt: now,
		ExpiresAt: now.Add(s.ttl),
	}

	s.mu.Lock()
	s.pruneLocked(now)
	s.sessions[session.ID] = session
	s.mu.Unlock()

	return *session, nil
}

// Lookup returns a live session, verifying that the device is a participant.
func (s *Store) Lookup(id, deviceID string) (Session, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	session, ok := s.sessions[id]
	if !ok {
		return Session{}, ErrUnknownSession
	}
	if !s.now().UTC().Before(session.ExpiresAt) {
		delete(s.sessions, id)
		return Session{}, ErrExpired
	}
	if session.From != deviceID && session.To != deviceID {
		return Session{}, ErrForbidden
	}
	return *session, nil
}

// Verify checks a ticket for a session identifier without consuming it.
func (s *Store) Verify(id, deviceID, ticket string) (Session, error) {
	session, err := s.Lookup(id, deviceID)
	if err != nil {
		return Session{}, err
	}
	presented, err := DecodeTicket(ticket)
	if err != nil {
		return Session{}, err
	}
	if subtle.ConstantTimeCompare(presented, session.Ticket) != 1 {
		return Session{}, ErrBadTicket
	}
	return session, nil
}

// Peer returns the other device of a session.
func (s Session) Peer(deviceID string) string {
	if deviceID == s.From {
		return s.To
	}
	return s.From
}

// Close removes a session.
func (s *Store) Close(id string) {
	s.mu.Lock()
	delete(s.sessions, id)
	s.mu.Unlock()
}

// Len reports the number of live sessions.
func (s *Store) Len() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.pruneLocked(s.now().UTC())
	return len(s.sessions)
}

func (s *Store) pruneLocked(now time.Time) {
	for id, session := range s.sessions {
		if !now.Before(session.ExpiresAt) {
			delete(s.sessions, id)
		}
	}
}
